assets/summary-review.css.new:
/* Complete paper copy when the native exercise disclosures are closed. */
@media print {
  .page-ai-summary-review .entry-jumps,
  .page-ai-summary-review a[download] { display:none!important; }
  .page-ai-summary-review .section-content details::details-content {
    content-visibility:visible!important; display:block!important;
  }
  .page-ai-summary-review .section-content details { break-inside:auto; background:white; color:black; }
  .page-ai-summary-review .section-content details > summary { list-style:none; }
  .page-ai-summary-review .section-content details > summary::marker { content:""; }
  .page-ai-summary-review .section-content details > summary::-webkit-details-marker { display:none; }
  .page-ai-summary-review .section-content details > p,
  .page-ai-summary-review .section-content details > pre { display:block!important; }
  .page-ai-summary-review .section-content details > pre {
    white-space:pre-wrap; overflow-wrap:anywhere; break-inside:auto; background:white; color:black;
  }
}

assets/ai-task-choice.css.new:
/* Print the entire private-use worksheet even when its disclosure is closed. */
@media print {
  .page-ai-task-choice a[download] { display:none!important; }
  .page-ai-task-choice .choice-sheet::details-content {
    content-visibility:visible!important; display:block!important;
  }
  .page-ai-task-choice .choice-sheet { break-inside:auto; background:white; color:black; }
  .page-ai-task-choice .choice-sheet > summary { list-style:none; }
  .page-ai-task-choice .choice-sheet > summary::marker { content:""; }
  .page-ai-task-choice .choice-sheet > summary::-webkit-details-marker { display:none; }
  .page-ai-task-choice .choice-sheet > pre {
    display:block!important; white-space:pre-wrap; overflow-wrap:anywhere;
    break-inside:auto; background:white; color:black;
  }
}
